-- Every XP evoker sold or generated by the content catalog needs a real
-- resolver. Missing effects must fail before a player can select the item.
local catalog = require("policy.catalog")
local categories = require("constants.catalog")
local effects = require("policy.inventory.evokers.effects")
local harness = require("tests.harness")

local test = {}

-- Check the effective catalog, including any modded subtype in this run.
function test.run()
    for _, item in ipairs(catalog.all(categories.ITEMS)) do
        if item.evoker then
            local effect = effects.get(item.id)

            harness.truthy(effect, "missing effect for " .. item.id)
            harness.truthy(type(effect.resolve) == "function")
        end
    end
end

return test
